    private record Events(Map<String, Value> mapping, boolean tracked, java.util.Set<String> locals,
            java.util.Set<String> request, Map<String, Value> parameters, Map<String, Value> graphs) { }
    private static Map<Events, Integer> eventBag(List<BindingSet> rows) {
        Map<Events, Integer> result = new HashMap<>();
        for (BindingSet row : rows) {
            Map<String, Value> mapping = new LinkedHashMap<>();
            for (String name : row.getBindingNames()) if (row.hasBinding(name)) mapping.put(name, row.getValue(name));
            var origin = BindingSetOrigin.of(row);
            result.merge(new Events(Collections.unmodifiableMap(mapping), BindingSetOrigin.isTrackedInput(row),
                    origin.localNames(), origin.requestNames(), origin.retainedParametersForTransport(),
                    GraphFrameBindings.from(row).retainedParametersForTransport()), 1, Integer::sum);
        }
        return result;
    }

    private void execute(Path path, String query, int count, TestReporter reporter) {
        String flag = "rdf4j.lmdb.nativeQueryEngine.enabled", previous = System.getProperty(flag);
        System.setProperty(flag, "true");
        var store = new LmdbStore(path.toFile(), config());
        var repository = new SailRepository(store);
        try {
            repository.init();
            assertInstanceOf(LmdbNativeEvaluationStrategyFactory.class, store.getEvaluationStrategyFactory());
            List<Statement> detached = new ArrayList<>();
            try (var connection = repository.getConnection(); var statements = connection.getStatements(null, null, null, false)) {
                while (statements.hasNext()) detached.add(detach(statements.next()));
            }
            // Use the actual persisted lexical values, with an ordinary scanning TripleSource. No fabricated ID,
            // descriptor, observation or native equality certificate is introduced by this independent oracle.
            var source = new LmdbNativeRepeatedStatementTermRoleTest.MemorySource(detached, NativeCompositeOriginFixture.iri("extra"));
            var ordinary = new DefaultEvaluationStrategy(source, (FederatedServiceResolver) null);
            List<BindingSet> expected;
            try (var rows = ordinary.precompile(NativeCompositeOriginFixture.parse(query)).evaluate(org.eclipse.rdf4j.query.impl.EmptyBindingSet.getInstance())) {
                expected = QueryResults.asList(rows);
            }
            assertEquals(count, expected.size(), "independent ordinary result from actual persisted data");
            assertEquals(1, expected.stream().filter(row -> row.getValue("key") instanceof BNode).count());
            assertEquals(1, expected.stream().filter(row -> row.getValue("key") instanceof IRI).count());
            assertEquals(1, expected.stream().filter(row -> row.getValue("key") instanceof TripleTerm).count());
            assertEquals(2, expected.stream().filter(row -> !row.hasBinding("v")).count());
            try (var connection = repository.getConnection()) {
                List<BindingSet> actual;
                try (var rows = connection.prepareTupleQuery(query).evaluate()) { actual = QueryResults.asList(rows); }
                reporter.publishEntry(Map.of("ordinaryCount", String.valueOf(expected.size()), "nativeCount", String.valueOf(actual.size()),
                        "classification", "resource-domain feature route"));
                assertEquals(bag(expected), bag(actual), "exact actual stored-value bag, before route assertions");
                GenericPlanNode plan = connection.prepareTupleQuery(query).explain(Explanation.Level.Telemetry).toGenericPlanNode();
                assertEquals("lmdb-native", plan.getStringMetricPlanned("plannedExecutionEngine"));
                assertTrue(composed(plan), "real public resource-key OPTIONAL owner, beyond separately native leaves");
            }
        } finally {
            try { repository.shutDown(); } finally {
                if (previous == null) System.clearProperty(flag); else System.setProperty(flag, previous);
            }
        }
    }

    private void write(Path path, List<Statement> statements) {
        var repository = new SailRepository(new LmdbStore(path.toFile(), config()));
        try {
            repository.init();
            try (var connection = repository.getConnection()) { connection.add(statements); }
        } finally { repository.shutDown(); }
    }
