        if (value instanceof BNode blank) return vf.createBNode(blank.getID());
        if (value instanceof TripleTerm triple) return vf.createTripleTerm((Resource) detach(triple.getSubject()),
                (IRI) detach(triple.getPredicate()), detach(triple.getObject()));
        Literal literal = (Literal) value;
        return literal.getLanguage().isPresent() ? vf.createLiteral(literal.getLabel(), literal.getLanguage().orElseThrow())
                : vf.createLiteral(literal.getLabel(), vf.createIRI(literal.getDatatype().stringValue()));
